package org.sigf;
import org.sigf.app.*; import org.sigf.config.*; import org.sigf.security.*; import org.sigf.services.*; import org.sigf.ui.*; import org.sigf.domain.*;

import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.flywaydb.core.Flyway;import java.sql.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="SIGF_UPGRADE_TEST",matches="true")
class MigrationUpgradeTest {
 @Test void existingProductRequiresTaxClassification() throws Exception {String url=System.getenv("SIGF_UPGRADE_DB_URL"),user=System.getenv("SIGF_DB_USER"),password=System.getenv("SIGF_DB_PASSWORD");assertTrue(url.endsWith("/sigf_javafx_upgrade_test"));Flyway.configure().dataSource(url,user,password).target("3").load().migrate();try(Connection c=DriverManager.getConnection(url,user,password);Statement s=c.createStatement()){s.executeUpdate("insert into product(code,name,sale_price,category,laboratory) values('OLD','Existente',10.00,'Categoría histórica','Laboratorio histórico')");s.executeUpdate("insert into app_user(username,password_hash,role) values('test-user','test-hash','ADMIN')");s.executeUpdate("insert into batch(product_id,lot,expires_on,quantity) select id,'LEGACY',current_date+30,2 from product where code='OLD'");s.executeUpdate("insert into sale(request_id,created_by,subtotal,tax,total) select '00000000-0000-0000-0000-000000000111',id,10.00,0.00,10.00 from app_user where username='test-user'");s.executeUpdate("insert into sale_line(sale_id,product_id,batch_id,quantity,unit_price) select s.id,p.id,b.id,1,10.00 from sale s cross join product p join batch b on b.product_id=p.id where p.code='OLD'");}Flyway.configure().dataSource(url,user,password).load().migrate();try(Connection c=DriverManager.getConnection(url,user,password);Statement s=c.createStatement();ResultSet r=s.executeQuery("select tax_rate from product where code='OLD'")){assertTrue(r.next());assertNull(r.getBigDecimal(1));}try(Connection c=DriverManager.getConnection(url,user,password);Statement s=c.createStatement();ResultSet r=s.executeQuery("select count(*) from product_catalog where (kind='category' and name='Categoría histórica') or (kind='laboratory' and name='Laboratorio histórico')")){assertTrue(r.next());assertEquals(2,r.getInt(1));}try(Connection c=DriverManager.getConnection(url,user,password);Statement s=c.createStatement();ResultSet r=s.executeQuery("select s.total,l.product_name_snapshot,h.sale_id,d.sale_id from sale s join sale_line l on l.sale_id=s.id left join sale_receipt_snapshot h on h.sale_id=s.id left join internal_document d on d.sale_id=s.id where s.request_id='00000000-0000-0000-0000-000000000111'")){assertTrue(r.next());assertEquals(0,new java.math.BigDecimal("10.00").compareTo(r.getBigDecimal(1)));assertNull(r.getString(2));assertNull(r.getObject(3));assertNull(r.getObject(4));}}
}
